#!/bin/bash

ssh lustretest-mgs "sudo /sbin/modprobe zfs; sudo sgdisk --zap-all /dev/sda; sudo sgdisk --zap-all /dev/sdb; sudo zpool create -f -o ashift=12 -O overlay=on -O atime=off -O dnodesize=auto lustre.mdt /dev/sda /dev/sdb; sudo mkfs.lustre --mgs --backfstype=zfs --fsname=lustest lustre.mdt/lustest-MGS0000; sudo mkfs.lustre --mdt --backfstype=zfs --fsname=lustest --index=0 --mgsnode=lustretest-mgs lustre.mdt/lustest-MDT0000; sudo mkdir -p /lustre.mdt/lustest-MGS0000; sudo mount -t lustre lustre.mdt/lustest-MGS0000 /lustre.mdt/lustest-MGS0000; sudo mkdir -p /lustre.mdt/lustest-MDT0000; sudo mount -t lustre lustre.mdt/lustest-MDT0000 /lustre.mdt/lustest-MDT0000"
for i in $(seq 0 15); do echo -e "setup lustretest-ost${i}\n\n" ;ssh lustretest-ost$i "sudo /sbin/modprobe zfs; sudo sgdisk --zap-all /dev/sda; sudo zpool create -f -o ashift=12 -O overlay=on -O atime=off -O recordsize=1M -O compression=lz4 -O dnodesize=auto lustre /dev/sda; INDEX=\$(printf "%x" $i); sudo mkfs.lustre --ost --backfstype=zfs --fsname=lustest --index=$i --mgsnode=lustretest-mgs lustre/lustest-OST000\$INDEX; sudo mkdir -p /lustre/lustest-OST000\$INDEX; sudo mount -t lustre lustre/lustest-OST000\$INDEX /lustre/lustest-OST000\$INDEX; sudo zfs set primarycache=none lustre/lustest-OST000\$INDEX"; done
for i in $(seq 16 23); do echo -e "setup lustretest-ost${i}\n\n" ; ssh lustretest-ost$i "sudo /sbin/modprobe zfs; sudo sgdisk --zap-all /dev/sda; sudo zpool create -f -o ashift=12 -O overlay=on -O atime=off -O recordsize=1M -O compression=lz4 -O dnodesize=auto lustre /dev/sda; INDEX=\$(printf "%x" $i); sudo mkfs.lustre --ost --backfstype=zfs --fsname=lustest --index=$i --mgsnode=lustretest-mgs lustre/lustest-OST00\$INDEX; sudo mkdir -p /lustre/lustest-OST00\$INDEX; sudo mount -t lustre lustre/lustest-OST00\$INDEX /lustre/lustest-OST00\$INDEX; sudo zfs set primarycache=none lustre/lustest-OST00\$INDEX"; done
